// Changes: Retain token ownership across Snow assertion jumps and release
// preceding TEXT values.
static TokenType read_token(Ctx* ctx) {
  if (current_token.value_type == TEXT) {
    free(current_token.value.text);
    current_token.value_type = INTEGER;
  }
  current_token = next_token(ctx);
  return current_token.type;
}

