// Changes: Match combined literal fragments while retaining the next token and assertion-safe TEXT ownership.
static TokenType read_literal(Ctx* ctx, const char* expected) {
  size_t length = strlen(expected);
  size_t matched = 0;
  TokenType type;
  while ((type = read_token(ctx)) == STRING) {
    asserteq(current_token.value_type, TEXT);
    size_t fragment_length = strlen(current_token.value.text);
    assert(fragment_length <= length - matched);
    assert(memcmp(current_token.value.text, expected + matched,
                  fragment_length) == 0);
    matched += fragment_length;
  }
  asserteq(matched, length);
  return type;
}

